  "sql": "SELECT h.hotel_id, SUM(n.nightly_rate_cents) AS total_cents FROM saved_hotels h JOIN saved_hotel_zips z ON h.hotel_id = z.hotel_id JOIN demo_hotel_nights n ON h.hotel_id = n.hotel_id WHERE z.postcode = :postcode AND n.stay_date >= :check_in AND n.stay_date < :check_out GROUP BY h.hotel_id HAVING COUNT(*) = julianday(:check_out) - julianday(:check_in) AND MIN(n.rooms_available) >= 1 ORDER BY total_cents, h.hotel_id LIMIT 3",
